1	// Per-workspace overlay store: the things native tasks can't hold —
2	// cross-session dependency edges, richer statuses, and notes. Persisted to disk so it
3	// survives daemon restarts and is shared by every session in the workspace.
4	'use strict';
5	const fs = require('fs');
6	const os = require('os');
7	const path = require('path');
8	const crypto = require('crypto');
9	const { encodeWorkspace } = require('./native-tasks');
10	const graphStore = require('./graph-store');
11	
12	const BASE = process.env.CLAUDE_PLUGIN_DATA || path.join(os.homedir(), '.claude', 'orchestrator');
13	const DIR = path.join(BASE, 'overlay');
14	// edges: cross-session/workspace deps · status: richer-status overrides · notes: freeform
15	// summaries: on-complete "interface" summary per task (Tier-1 context) · knowledge: Tier-2
16	// context items per task · assignee: which agent is working a task (for live animation)
17	// timestamps: per-task { firstSeen, lastChanged, lastStatus } — daemon-observed task lifecycle
18	// git: per-task { branch, worktree, head, createdAt } — the isolated attempt worktree for a task
19	// repos: per-task absolute path of the TARGET git repo the loop should branch/measure/merge on,
20	//   when it differs from the daemon workspace. Absent ⇒ fall back to the workspace (back-compat).
21	// metrics: per-task INLINE metric spec for the metric-driven loop — { metric, direction (min|max),
22	//   measure_command, parse?, target?, guardrails? }. The objective an attempt's measure node runs &
23	//   the judge weighs. Absent ⇒ no metric (rationale-only judging, back-compat).
24	// measurements: per-task measured value(s) the measure node produced — { value, guardrails:{...},
25	//   measured_at, command, baseline?:{ value, guardrails, measured_at } }. `baseline` is the target
26	//   repo's current-main reference (no attempt applied) the judge weighs attempts against.
27	// benchmarks: per-task researched competitor/industry-average reference for the metric — { metric,
28	//   value, unit?, source, note?, confidence? (low|med|high), researched_at? }. The EXTERNAL axis the
29	//   judge compares the winning attempt's measured value against (beyond our own baseline). Absent ⇒
30	//   baseline-only judging (back-compat). Set by the self-learn-benchmark research agent.
31	// cancel_requested: per-task ISO timestamp — advisory cooperative-cancel flag set when a task is
32	//   canceled, so an in-flight worker can poll and self-terminate (cancel-wins concurrency).
33	// stop_requested: per-agent_id ISO timestamp — advisory cooperative-stop flag (cross-session agent
34	//   control). The worker polls it and self-terminates; no cross-process kill.
35	// guidance: escalation queue — items { id, question, context, trigger, ts, resolved, answer? }.
36	//   A pending (unresolved) item halts the autonomous loop until the user answers.
37	// optimize: per-problem converged-vs-iterate bookkeeping for the metric-driven loop (⑥) —
38	//   { closed?:bool, decision?, verdicts?:int (verdict count at last decision), at? }. `closed` ⇒
39	//   the loop has stopped iterating this problem (converged/budget/stuck); `verdicts` lets the loop
40	//   re-decide ONLY after a NEW judge round lands (count increased), so an 'iterate' can't tight-loop.
41	// epoch: monotonic counter bumped whenever a note/task node is ADDED — the "the graph changed"
42	//   watermark the incremental edge-judge keys off of. judgedAtEpoch: per-note-key map (key ->
43	//   epoch at which it was last adjudicated; absent/0 = never). A note is re-pullable by the judge
44	//   only when judgedAtEpoch[key] < epoch, so a 'no edge' verdict (stamps =epoch) keeps it out of the
45	//   queue until the graph actually changes. judgeCursor: persisted position the judge walks the work
46	//   queue from (advances + wraps across ticks; survives daemon restart so it never re-walks the whole
47	//   graph). All three are part of the RAG-candidate → agent-adjudicator edge pipeline (see lib/judge.js).
48	// judgedClusters: per dup-cluster-signature map (signature -> epoch at which the cluster was last
49	//   adjudicated by the node-judge). A cluster is re-judgeable only when its stored epoch < epoch OR
50	//   its membership (hence signature) changed — the NODE-dedup analogue of judgedAtEpoch for edges.
51	// snapshots: per-task frozen copy of native fields ({ subject, description, status, blockedBy,
52	//   owner, metadata, snapshotted_at }) captured when the task reaches a terminal status. Claude
53	//   Code's cleanupPeriodDays retention sweep also garbage-collects ~/.claude/tasks/, so native
54	//   files are NOT indefinitely durable — aggregateWorkspace falls back to this snapshot when the
55	//   native file is gone, keeping completed nodes in the graph. Also the substrate for DAEMON-
56	//   ORIGINATED follow-up tasks (keys 'followup/<id>', non-terminal status, no native file ever
57	//   exists — see lib/followups.js): same fallback serves them as live graph nodes.
58	// distinctClusters: per dup-cluster-signature map (signature -> ISO timestamp) marking a cluster the
59	//   user definitively judged DISTINCT ("don't ask again"). dupClusters/the judge queue SKIP any
60	//   signature present here forever — a deliberate, user-made call (only the user can say two
61	//   same-recall notes are genuinely different facts). Unlike judgedClusters (epoch-gated, re-judgeable
62	//   when membership/epoch changes) this is permanent for that exact member set.
63	const EMPTY = () => ({ edges: [], unwired: {}, status: {}, notes: {}, summaries: {}, knowledge: {}, assignee: {}, timestamps: {}, config: {}, git: {}, repos: {}, metrics: {}, measurements: {}, benchmarks: {}, note_nodes: {}, snapshots: {}, cancel_requested: {}, stop_requested: {}, guidance: [], optimize: {}, epoch: 0, judgedAtEpoch: {}, judgeCursor: 0, judgedClusters: {}, distinctClusters: {}, forceClaims: {} });
64	
65	// Default relevance weight for context edges (0..1). Pre-existing context edges with no stored
66	// `weight` read as this, so the field is backward-compatible (substrate for relevance traversal).
67	const DEFAULT_CONTEXT_WEIGHT = 0.5;
68	// Read an edge's relevance weight: only context edges carry one; absent ⇒ default. Returns null for
69	// non-context edges (blocking/supersede carry no weight). Clamps to [0,1] defensively.
70	function edgeWeight(e) {
71	  if (!e || e.kind !== 'context') return null;
72	  const w = typeof e.weight === 'number' ? e.weight : DEFAULT_CONTEXT_WEIGHT;
73	  return Math.max(0, Math.min(1, w));
74	}
75	
76	// Collision-free overlay filename: encodeWorkspace is lossy (both `/` and `.` → `-`), so distinct
77	// workspaces could map to ONE file and clobber each other (review H2). Use a content hash, keeping a
78	// readable basename prefix for debuggability.
79	function fileFor(workspace) {
80	  const h = crypto.createHash('sha1').update(String(workspace || '')).digest('hex').slice(0, 16);
81	  const base = (path.basename(String(workspace || '')) || 'ws').replace(/[^A-Za-z0-9._-]/g, '_');
82	  return path.join(DIR, `${base}-${h}.json`);
83	}
84	// Pre-hash filename — read for one-time migration of overlays written before the H2 fix.
85	function legacyFileFor(workspace) {
86	  return path.join(DIR, `${encodeWorkspace(workspace)}.json`);
87	}
88	
89	// Collision-free diagnostics filename (separate from overlay config, survives regeneration).
90	function diagnosticsFileFor(workspace) {
91	  const h = crypto.createHash('sha1').update(String(workspace || '')).digest('hex').slice(0, 16);
92	  const base = (path.basename(String(workspace || '')) || 'ws').replace(/[^A-Za-z0-9._-]/g, '_');
93	  return path.join(DIR, `${base}-${h}.diagnostics.json`);
94	}
95	
96	function load(workspace) {
97	  let base;
98	  let o = null;
99	  try { o = JSON.parse(fs.readFileSync(fileFor(workspace), 'utf8')); }
100	  catch { try { o = JSON.parse(fs.readFileSync(legacyFileFor(workspace), 'utf8')); } catch { o = null; } }
101	  base = o ? { ...EMPTY(), ...o } : EMPTY();
102	
103	  // Rehydrate shared fields from graph-store (edges, status, summaries, knowledge, note_nodes, snapshots).
104	  // Wrapped in try/catch — must never break load() for workspaces with no graph yet.
105	  try {
106	    const store = graphStore.forWorkspace(workspace);
107	    const g = graphStore.loadGraph(store);
108	
109	    // edges
110	    if (g.edges.length) base.edges = g.edges;
111	
112	    // Process both live nodes and checkpointed nodes the same way.
113	    const allNodes = { ...g.checkpointed, ...g.nodes };
114	    for (const [id, node] of Object.entries(allNodes)) {
115	      // status — skip the 'ready' sentinel: emitDiff writes status:'ready' when an override
116	      // was DELETED (releaseClaim / verdict release), because the append-only log can't express
117	      // deletion. Re-importing it as an explicit override would short-circuit dep derivation
118	      // (an override always wins in the scheduler), so 'ready' replays as "no override".
119	      if (node.status != null && node.status !== 'ready') base.status[id] = node.status;
120	
121	      // summaries
122	      if (node.summary != null) base.summaries[id] = node.summary;
123	
124	      // knowledge
125	      if (Array.isArray(node.knowledge) && node.knowledge.length > 0) base.knowledge[id] = node.knowledge;
126	
127	      // note_nodes — reconstruct from graph node shape
128	      // Node keys are stored as 'note:' + bareId; strip the prefix so note_nodes
129	      // is keyed by the bare noteId (matching what addNoteNode returns).
130	      if (node.kind === 'note' && node.note) {
131	        const bareId = id.startsWith('note:') ? id.slice(5) : id;
132	        base.note_nodes[bareId] = {
133	          id: bareId,
134	          title:      node.note.title      || null,
135	          summary:    node.note.summary    || null,
136	          created_by: node.note.created_by || null,
137	          created_at: node.note.valid_from || null,
138	          validFrom:  node.note.valid_from || null,
139	          knowledge:  Array.isArray(node.knowledge) ? node.knowledge : [],
140	          vec:        Array.isArray(node.vec) ? node.vec : null,
141	          validTo:     node.validTo     || null,
142	          supersededBy: node.supersededBy || null,
143	          supersedes:  node.supersedes  || null,
144	        };
145	      }
146	
147	      // snapshots
148	      if (node.snapshot != null) base.snapshots[id] = node.snapshot;
149	
150	      // assignee
151	      if (node.assignee != null) base.assignee[id] = node.assignee;
152	
153	      // timestamps
154	      if (node.timestamps != null) base.timestamps[id] = node.timestamps;
155	
156	      // metrics
157	      if (node.metrics != null) base.metrics[id] = node.metrics;
158	
159	      // measurements
160	      if (node.measurements != null) base.measurements[id] = node.measurements;
161	    }
162	
163	    // benchmarks (stored on system:benchmarks node)
164	    const benchNode = allNodes['system:benchmarks'];
165	    if (benchNode && benchNode.benchmarks) base.benchmarks = benchNode.benchmarks;
166	
167	    // repos (stored on system:repos node)
168	    const reposNode = allNodes['system:repos'];
169	    if (reposNode && reposNode.repos) base.repos = reposNode.repos;
170	  } catch { /* graph-store not yet initialised — fall back to empty shared fields */ }
171	
172	  // Rehydrate diagnostics from separate storage
173	  try {
174	    const diag = getDiagnostics(workspace);
175	    if (diag) base.diagnostics = diag;
176	  } catch { /* diagnostics file not yet created or corrupt — fall back to empty */ }
177	
178	  // Set prev-state baseline so the next emitDiff diff starts from the correct state
179	  // (otherwise it would re-emit everything as "new").
180	  try { graphStore.setPrevState(workspace, base); } catch { /* best-effort */ }
181	
182	  return base;
183	}
184	
185	function save(workspace, overlay, opts = {}) {
186	  fs.mkdirSync(DIR, { recursive: true });
187	  const dest = fileFor(workspace);
188	  const tmp = `${dest}.${process.pid}.tmp`;            // atomic write: temp + rename (review H1)
189	  const LOCAL_FIELDS = [
190	    'git', 'cancel_requested', 'stop_requested', 'config', 'unwired',
191	    'judgedAtEpoch', 'judgeCursor', 'judgedClusters', 'distinctClusters',
192	    // No graph-store event type covers these; without them here they'd be silently
193	    // dropped on every save/load round-trip (notes/guidance/optimize/epoch).
194	    'notes', 'guidance', 'optimize', 'epoch',
195	    // force-claim cap counters — must persist across daemon restarts
196	    'forceClaims',
197	  ];
198	  const localOnly = Object.fromEntries(LOCAL_FIELDS.map(k => [k, overlay[k] ?? EMPTY()[k]]));
199	  fs.writeFileSync(tmp, JSON.stringify(localOnly, null, 2));
200	  fs.renameSync(tmp, dest);
201	  if (opts.deferred) {
202	    setImmediate(() => { try { emitDiff(workspace, overlay); } catch {} });
203	  } else {
204	    try { emitDiff(workspace, overlay); } catch { /* best-effort — never break the overlay save */ }
205	  }
206	}
207	
208	// Emit graph-store events for any shared fields that changed since the last save.
209	// Wrapped in try/catch by the caller — failures must not surface to callers of save().
210	function emitDiff(workspace, overlay) {
211	  const store = graphStore.forWorkspace(workspace);
212	  const prev  = graphStore.getPrevState(workspace);
213	  const ts    = new Date().toISOString();
214	
215	  // edges — emit edge_added for each edge not in prev (matched by from+to+kind+fromWorkspace)
216	  const prevEdgeSigs = new Set(
217	    (prev.edges || []).map((e) => `${e.from}\0${e.to}\0${e.kind || 'blocking'}\0${e.fromWorkspace || ''}`)
218	  );
219	  for (const e of (overlay.edges || [])) {
220	    const sig = `${e.from}\0${e.to}\0${e.kind || 'blocking'}\0${e.fromWorkspace || ''}`;
221	    if (prevEdgeSigs.has(sig)) continue;
222	    const ev = { evt: 'edge_added', from: e.from, to: e.to, kind: e.kind || 'blocking', actor: 'overlay-sync', ts };
223	    if (e.fromWorkspace) ev.fromWorkspace = e.fromWorkspace;
224	    if (typeof e.weight === 'number') ev.weight = e.weight;
225	    graphStore.appendEvent(store, e.from, ev);
226	  }
227	
228	  // status — emit status_changed for each key whose value changed
229	  for (const [nodeId, status] of Object.entries(overlay.status || {})) {
230	    if ((prev.status || {})[nodeId] === status) continue;
231	    graphStore.appendEvent(store, nodeId, { evt: 'status_changed', id: nodeId, workspace, status, actor: 'overlay-sync', ts });
232	  }
233	  // status cleared — a key present in prev but now ABSENT had its override deleted (releaseClaim:
234	  // a swept/stale claim re-derives to available). The event log is append-only, so without an
235	  // explicit event the persisted store would keep replaying the stale 'in_progress' on the next
236	  // load(). Emit 'ready' so the released state survives a daemon restart (restart resilience).
237	  for (const nodeId of Object.keys(prev.status || {})) {
238	    if (Object.prototype.hasOwnProperty.call(overlay.status || {}, nodeId)) continue;
239	    graphStore.appendEvent(store, nodeId, { evt: 'status_changed', id: nodeId, workspace, status: 'ready', actor: 'overlay-sync', ts });
240	  }
241	
242	  // summaries — emit summary_set for each key whose value changed
243	  for (const [nodeId, summary] of Object.entries(overlay.summaries || {})) {
244	    if ((prev.summaries || {})[nodeId] === summary) continue;
245	    graphStore.appendEvent(store, nodeId, { evt: 'summary_set', id: nodeId, workspace, summary, actor: 'overlay-sync', ts });
246	  }
247	
248	  // knowledge — emit knowledge_added for each new item beyond the previously seen count
249	  for (const [nodeId, items] of Object.entries(overlay.knowledge || {})) {
250	    if (!Array.isArray(items)) continue;
251	    const prevLen = (prev.knowledge || {})[nodeId] || 0;
252	    for (let i = prevLen; i < items.length; i++) {
253	      graphStore.appendEvent(store, nodeId, { evt: 'knowledge_added', id: nodeId, workspace, item: items[i], actor: 'overlay-sync', ts });
254	    }
255	  }
256	
257	  // note_nodes — emit note_created for each key not in prev
258	  for (const [noteId, n] of Object.entries(overlay.note_nodes || {})) {
259	    if ((prev.note_nodes || {})[noteId]) continue;
260	    graphStore.appendEvent(store, 'note:' + noteId, { evt: 'note_created', id: noteId, workspace, title: n.title, summary: n.summary, created_by: n.created_by, valid_from: n.validFrom || n.valid_from, vec: Array.isArray(n.vec) ? n.vec : null, actor: 'overlay-sync', ts });
261	  }
262	
263	  // snapshots — emit snapshot_stored for each new key or changed snapshotted_at
264	  for (const [nodeId, snap] of Object.entries(overlay.snapshots || {})) {
265	    const prevSnap = (prev.snapshots || {})[nodeId];
266	    if (prevSnap && prevSnap.snapshotted_at === snap.snapshotted_at) continue;
267	    graphStore.appendEvent(store, nodeId, { evt: 'snapshot_stored', id: nodeId, workspace, subject: snap.subject, description: snap.description, status: snap.status, blockedBy: snap.blockedBy, owner: snap.owner, metadata: snap.metadata, snapshotted_at: snap.snapshotted_at, actor: 'overlay-sync', ts });
268	  }
269	
270	  // assignee — emit assignee_set for each key whose value changed
271	  for (const [nodeId, assignee] of Object.entries(overlay.assignee || {})) {
272	    if (JSON.stringify((prev.assignee || {})[nodeId]) === JSON.stringify(assignee)) continue;
273	    graphStore.appendEvent(store, nodeId, { evt: 'assignee_set', id: nodeId, workspace, assignee, actor: 'overlay-sync', ts });
274	  }
275	
276	  // timestamps — emit timestamps_set for each key whose value changed
277	  for (const [nodeId, timestamps] of Object.entries(overlay.timestamps || {})) {
278	    if (JSON.stringify((prev.timestamps || {})[nodeId]) === JSON.stringify(timestamps)) continue;
279	    graphStore.appendEvent(store, nodeId, { evt: 'timestamps_set', id: nodeId, workspace, timestamps, actor: 'overlay-sync', ts });
280	  }
281	
282	  // metrics — emit metrics_set for each key whose value changed
283	  for (const [nodeId, metrics] of Object.entries(overlay.metrics || {})) {
284	    if (JSON.stringify((prev.metrics || {})[nodeId]) === JSON.stringify(metrics)) continue;
285	    graphStore.appendEvent(store, nodeId, { evt: 'metrics_set', id: nodeId, workspace, metrics, actor: 'overlay-sync', ts });
286	  }
287	
288	  // measurements — emit measurements_set for each key whose value changed
289	  for (const [nodeId, measurements] of Object.entries(overlay.measurements || {})) {
290	    if (JSON.stringify((prev.measurements || {})[nodeId]) === JSON.stringify(measurements)) continue;
291	    graphStore.appendEvent(store, nodeId, { evt: 'measurements_set', id: nodeId, workspace, measurements, actor: 'overlay-sync', ts });
292	  }
293	
294	  // benchmarks — emit benchmarks_set on system:benchmarks node for any change
295	  if (overlay.benchmarks && JSON.stringify(prev.benchmarks || {}) !== JSON.stringify(overlay.benchmarks)) {
296	    graphStore.appendEvent(store, 'system:benchmarks', { evt: 'benchmarks_set', workspace, benchmarks: overlay.benchmarks, actor: 'overlay-sync', ts });
297	  }
298	
299	  // repos — emit repo_config_set on system:repos node for any change
300	  if (overlay.repos && JSON.stringify(prev.repos || {}) !== JSON.stringify(overlay.repos)) {
301	    graphStore.appendEvent(store, 'system:repos', { evt: 'repo_config_set', workspace, repos: overlay.repos, actor: 'overlay-sync', ts });
302	  }
303	
304	  graphStore.setPrevState(workspace, overlay);
305	}
306	
307	// Add a dependency edge from -> to. Idempotent.
308	//   kind 'blocking' (default): `to` is blocked by `from` (scheduling — gates readiness).
309	//   kind 'context': non-blocking provenance — `from`'s summary flows into `to` as Tier-1
310	//     context even when `from` is already done. Lets new tasks pull existing nodes' summaries
311	//     without making the graph a flat list of roots.
312	//   kind 'supersede': non-blocking replacement link from=OLD -> to=NEW. Does NOT gate readiness
313	//     and does NOT flow summaries; it only records that `from` was retired in favor of `to`, so a
314	//     replan reads as old→new instead of leaving orphaned canceled duplicates beside fresh ones.
315	// fromWorkspace set ⇒ ghost edge: the provider `from` lives in another workspace.
316	// Stored in the CONSUMER's overlay (the workspace owning `to`).
317	// weight (0..1, context edges only): optional relevance scalar for spreading-activation traversal.
318	// Absent ⇒ DEFAULT_CONTEXT_WEIGHT when read back. Ignored for blocking/supersede edges.
319	function addEdge(overlay, from, to, fromWorkspace, kind, weight) {
320	  const fw = fromWorkspace || null;
321	  // Wiring an edge clears the unwired quarantine on either endpoint — the task is now
322	  // structurally connected to the graph (see daemon.js unwired stamp + /mark-root).
323	  if (overlay.unwired) { delete overlay.unwired[to]; delete overlay.unwired[from]; }
324	  const w = (kind === 'context' && typeof weight === 'number') ? Math.max(0, Math.min(1, weight)) : undefined;
325	  const existing = overlay.edges.find((e) => e.from === from && e.to === to && (e.fromWorkspace || null) === fw);
326	  if (existing) {
327	    if (kind === 'context') { existing.kind = 'context'; if (w !== undefined) existing.weight = w; }   // upgrade blocking → context on re-add (never silently downgrade)
328	    else if (kind === 'supersede') existing.kind = 'supersede';
329	    return overlay;
330	  }
331	  const edge = { from, to };
332	  if (fromWorkspace) edge.fromWorkspace = fromWorkspace;
333	  if (kind === 'context' || kind === 'supersede') edge.kind = kind; // omit for blocking (absent = blocking, back-compat)
334	  if (w !== undefined) edge.weight = w; // omit when unspecified (absent = DEFAULT_CONTEXT_WEIGHT, back-compat)
335	  overlay.edges.push(edge);
336	  return overlay;
337	}
338	
339	// Remove dependency edge(s) from -> to. Idempotent (no-op if none match). Mirrors addEdge's
340	// match on (from, to, fromWorkspace). If kind is given, only edges of that kind are removed
341	// ('blocking' = absent/!=context; 'context' = kind==='context'); otherwise all matches go.
342	// Lets a graph be re-parallelized by dropping stale prerequisite edges. Returns overlay.
343	function removeEdge(overlay, from, to, fromWorkspace, kind) {
344	  const fw = fromWorkspace || null;
345	  overlay.edges = overlay.edges.filter((e) => {
346	    if (!(e.from === from && e.to === to && (e.fromWorkspace || null) === fw)) return true;
347	    if (kind === 'context') return e.kind !== 'context';
348	    if (kind === 'blocking') return e.kind === 'context';
349	    return false; // no kind filter: drop every match
350	  });
351	  return overlay;
352	}
353	
354	function setStatus(overlay, key, status, note) {
355	  overlay.status[key] = status;
356	  if (note != null) overlay.notes[key] = String(note).slice(0, 280);
357	  return overlay;
358	}
359	
360	// Record/merge the git attempt worktree info for a task. Stamps createdAt on first write.
361	function setGit(overlay, key, info) {
362	  overlay.git[key] = { ...(overlay.git[key] || { createdAt: new Date().toISOString() }), ...info };
363	  return overlay;
364	}
365	
366	// Set (or clear, with a falsy repoPath) the target repo path a task's git ops should run against.
367	function setRepo(overlay, key, repoPath) {
368	  if (!overlay.repos) overlay.repos = {};
369	  if (repoPath) overlay.repos[key] = String(repoPath);
370	  else delete overlay.repos[key];
371	  return overlay;
372	}
373	
374	// Per-repo TEST COMMAND registry, keyed by ABSOLUTE repo path, nested under config (so it
375	// persists alongside the rest of the workspace config). Set (or clear, with a falsy cmd) how a
376	// repo's test suite is run. STORE/RETRIEVE ONLY — the daemon never executes these; agents
377	// (e.g. the nightly QA loop) look the command up and run it themselves.
378	function setTestCmd(overlay, repoPath, cmd) {
379	  if (!overlay.config) overlay.config = {};
380	  if (!overlay.config.test_cmds) overlay.config.test_cmds = {};
381	  if (cmd) overlay.config.test_cmds[String(repoPath)] = String(cmd);
382	  else delete overlay.config.test_cmds[repoPath];
383	  return overlay;
384	}
385	
386	// Read a repo's stored test command (null when unset / no repo).
387	function testCmdFor(overlay, repoPath) {
388	  return (repoPath && overlay.config && overlay.config.test_cmds && overlay.config.test_cmds[repoPath]) || null;
389	}
390	
391	// Set (or clear, with a falsy spec) the INLINE metric spec a task is optimizing. The spec shape
392	// is { metric, direction (min|max), measure_command, parse?, target?, guardrails? }; validation
393	// lives in the daemon endpoint — this just stores/clears what it's handed.
394	function setMetricSpec(overlay, key, spec) {
395	  if (!overlay.metrics) overlay.metrics = {};
396	  if (spec) overlay.metrics[key] = spec;
397	  else delete overlay.metrics[key];
398	  return overlay;
399	}
400	
401	// Merge measured value(s) onto a task node (the measure node's output). `data` is a partial —
402	// e.g. { value, guardrails, measured_at, command } for an attempt, or { baseline: {...} } for the
403	// repo's current-main reference — so an attempt measurement and its baseline can be set separately
404	// without clobbering each other. Pass a falsy data to clear the whole record.
405	function setMeasurement(overlay, key, data) {
406	  if (!overlay.measurements) overlay.measurements = {};
407	  if (data) overlay.measurements[key] = { ...(overlay.measurements[key] || {}), ...data };
408	  else delete overlay.measurements[key];
409	  return overlay;
410	}
411	
412	// Freeze a task's native fields into the overlay (see the `snapshots` field doc above). `data` is
413	// the snapshot record ({ subject, description, status, blockedBy, owner, metadata }); stamps
414	// snapshotted_at. Re-snapshotting a key overwrites — last terminal transition wins.
415	function setSnapshot(overlay, key, data) {
416	  if (!overlay.snapshots) overlay.snapshots = {};
417	  overlay.snapshots[key] = { ...data, snapshotted_at: new Date().toISOString() };
418	  return overlay;
419	}
420	
421	// Set (or clear, with falsy data) the researched competitor/industry-average benchmark for a task's
422	// metric. A record is { metric, value, unit?, source, note?, confidence?, researched_at? }; validation
423	// lives in the daemon endpoint — this just stores/clears what it's handed.
424	function setBenchmark(overlay, key, data) {
425	  if (!overlay.benchmarks) overlay.benchmarks = {};
426	  if (data) overlay.benchmarks[key] = data;
427	  else delete overlay.benchmarks[key];
428	  return overlay;
429	}
430	
431	// Add a "note node": an overlay-only graph node capturing durable conversation knowledge
432	// (a decision/finding) as a Tier-1 context provider. It is NOT a native todo — it lives only
433	// in the overlay and surfaces in the graph via buildGraph + context edges. Returns the id.
434	// `vec` (optional): a precomputed semantic embedding (384 floats) of the note's title+summary,
435	// stored beside the note for brute-force cosine retrieval in /search. The daemon computes it (embed
436	// is async; this store stays sync) — absent ⇒ the note falls back to lexical scoring (back-compat).
437	function addNoteNode(overlay, { title, summary, knowledge, created_by, valid_from, vec }) {
438	  // Collision-safe id: Date.now() alone collides for notes created in the same millisecond (back-to-
439	  // back record_decision / supersede calls would clobber each other). Append a short random suffix.
440	  let id;
441	  do { id = `note-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 5)}`; } while (overlay.note_nodes[id]);
442	  const created = new Date().toISOString();
443	  overlay.note_nodes[id] = {
444	    id,
445	    title: String(title || '').slice(0, 200),
446	    summary: String(summary || '').slice(0, 2000),
447	    knowledge: Array.isArray(knowledge) ? knowledge : [],
448	    created_by: created_by || null,
449	    created_at: created,
450	    // Truly bitemporal: two independent time axes, both queryable, for state-change reasoning (the Zep gap):
451	    //   VALID time — when the fact was true in the world. validFrom/validTo below; query via /search?asOf=T
452	    //     (the note CURRENT at T). validFrom defaults to creation but a caller may BACKDATE it.
453	    //   TRANSACTION time — when the KB LEARNED the fact. That's created_at (above), always = real
454	    //     insertion instant, never backdated; query via /search?knownAsOf=T (notes RECORDED by T). This
455	    //     is what stops a backdated valid_from from silently rewriting an earlier-knowledge query.
456	    //   The two compose: asOf=true-as-of-T1 & knownAsOf=recorded-by-T2 = the canonical bitemporal query.
457	    //
458	    //   validFrom — when this fact BECAME true (defaults to creation time; a caller may backdate it).
459	    //   validTo   — when it STOPPED being true (null ⇒ still current). Set when superseded, never
460	    //               deleting the row, so as-of retrieval can recover the fact CURRENT at any time.
461	    //   supersedes / supersededBy — the chain links (note id ↔ note id), history preserved.
462	    validFrom: valid_from ? String(valid_from) : created,
463	    validTo: null,
464	    supersedes: null,
465	    supersededBy: null,
466	    // Semantic embedding (384 floats) of title+summary for cosine retrieval; null ⇒ lexical fallback.
467	    vec: Array.isArray(vec) ? vec : null,
468	  };
469	  return id;
470	}
471	
472	// Supersede note `oldId` with `newId` WITHOUT deleting history: stamp validTo on the old note (when
473	// it stopped being true = the new note's validFrom), link old↔new both directions, and chain the new
474	// note's `supersedes` back. Idempotent-ish: re-linking the same pair just refreshes the stamps.
475	// Returns { ok, error? }. `at` (ISO) lets the caller set the changeover instant explicitly; absent ⇒
476	// the new note's validFrom (or now).
477	function supersedeNote(overlay, oldId, newId, at, workspace) {
478	  const nn = overlay.note_nodes || {};
479	  const oldN = nn[oldId];
480	  const newN = nn[newId];
481	  if (!oldN) return { ok: false, error: `unknown note ${oldId}` };
482	  if (!newN) return { ok: false, error: `unknown note ${newId}` };
483	  if (oldId === newId) return { ok: false, error: 'cannot supersede a note with itself' };
484	  const changeover = at ? String(at) : (newN.validFrom || new Date().toISOString());
485	  oldN.validTo = changeover;
486	  oldN.supersededBy = newId;
487	  newN.validFrom = changeover;          // the new fact becomes true exactly when the old one ends
488	  newN.supersedes = oldId;
489	  // Persist supersede relationship to graph-store so it survives daemon reload.
490	  if (workspace) {
491	    try {
492	      const store = graphStore.forWorkspace(workspace);
493	      graphStore.appendEvent(store, 'note:' + oldId, { evt: 'note_superseded', id: oldId, supersededBy: newId, validTo: changeover, ts: changeover, actor: 'supersede' });
494	      graphStore.appendEvent(store, 'note:' + newId, { evt: 'note_supersedes', id: newId, supersedes: oldId, ts: changeover, actor: 'supersede' });
495	    } catch { /* graph-store not yet initialised — in-memory only (back-compat) */ }
496	  }
497	  return { ok: true, at: changeover };
498	}
499	
500	// Walk the full supersede chain a note belongs to, oldest → newest, as an ordered list of ids.
501	// Pure read over note_nodes; follows supersedes backward to the root then supersededBy forward.
502	function noteChain(overlay, id) {
503	  const nn = overlay.note_nodes || {};
504	  if (!nn[id]) return [];
505	  let root = id;
506	  const seen = new Set();
507	  while (nn[root] && nn[root].supersedes && !seen.has(root)) { seen.add(root); root = nn[root].supersedes; }
508	  const chain = [];
509	  const fwd = new Set();
510	  let cur = root;
511	  while (nn[cur] && !fwd.has(cur)) { fwd.add(cur); chain.push(cur); cur = nn[cur].supersededBy; }
512	  return chain;
513	}
514	
515	// Push an escalation/guidance item onto the queue. Severity tiers: 'blocking' halts the autonomous
516	// loop (the caller sets loop.active=false); 'review' queues for the user WITHOUT pausing (judge
517	// housekeeping — supersede/dup-cluster confirmations). Anything else defaults to 'blocking' (safe:
518	// explicit escalations keep pausing). Returns the new item's id.
519	// `action` (optional): a structured, machine-actionable payload the dashboard renders into buttons and
520	// the resolver acts on without re-deriving anything. Shape is action-kind specific, e.g.
521	//   { kind:'dup-cluster', keys:[...], signature, notes:[{key,title,created_at}] }.
522	// Absent ⇒ a plain text-answer guidance item (unchanged, back-compat).
523	function addGuidance(overlay, { question, context, trigger, severity, action }) {
524	  if (!Array.isArray(overlay.guidance)) overlay.guidance = [];
525	  const id = `g-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
526	  const item = {
527	    id,
528	    question: String(question || '').slice(0, 1000),
529	    context: String(context || '').slice(0, 2000),
530	    trigger: trigger ? String(trigger).slice(0, 80) : null,
531	    severity: severity === 'review' ? 'review' : 'blocking',
532	    ts: new Date().toISOString(),
533	    resolved: false,
534	  };
535	  if (action && typeof action === 'object') item.action = action;   // structured, action-aware guidance
536	  overlay.guidance.push(item);
537	  return id;
538	}
539	
540	// Mark a guidance item resolved, recording the user's answer. Returns true if found.
541	function resolveGuidance(overlay, id, answer) {
542	  if (!Array.isArray(overlay.guidance)) return false;
543	  const it = overlay.guidance.find((g) => g.id === id);
544	  if (!it) return false;
545	  it.resolved = true;
546	  it.resolvedAt = new Date().toISOString();
547	  if (answer != null) it.answer = String(answer).slice(0, 2000);
548	  return true;
549	}
550	
551	// Stable signature of a dup-cluster = its sorted note keys joined by '|'. MUST match
552	// judge.clusterSignature so a signature marked distinct here is recognized by dupClusters/the queue.
553	// Kept local to avoid a circular require (judge.js → embed; overlay must stay dependency-light).
554	function clusterSig(keys) {
555	  return (Array.isArray(keys) ? keys.slice() : []).sort().join('|');
556	}
557	
558	// Permanently mark a dup-cluster signature as user-judged DISTINCT ("don't ask again"). dupClusters
559	// and the judge queue skip it forever. Idempotent; stamps the time of the decision. Returns the sig.
560	function markClusterDistinct(overlay, keys) {
561	  if (!overlay.distinctClusters) overlay.distinctClusters = {};
562	  const sig = clusterSig(keys);
563	  overlay.distinctClusters[sig] = new Date().toISOString();
564	  return sig;
565	}
566	
567	// Was this cluster signature definitively marked distinct by the user? Pure read.
568	function isClusterDistinct(overlay, keys) {
569	  const d = overlay.distinctClusters || {};
570	  return Object.prototype.hasOwnProperty.call(d, clusterSig(keys));
571	}
572	
573	// Lazy one-time severity migration: legacy items predate the field. Judge-housekeeping questions
574	// (supersede / dup-cluster confirmations) become 'review'; everything else stays 'blocking' (safe
575	// default). Stamps the item in place so the next overlay save persists it.
576	const REVIEW_PREFIXES = ['Possible supersede:', 'Ambiguous duplicate cluster'];
577	function guidanceSeverity(g) {
578	  if (g.severity !== 'blocking' && g.severity !== 'review') {
579	    g.severity = REVIEW_PREFIXES.some((p) => String(g.question || '').startsWith(p)) ? 'review' : 'blocking';
580	  }
581	  return g.severity;
582	}
583	
584	const pendingGuidance = (overlay) => (Array.isArray(overlay.guidance) ? overlay.guidance.filter((g) => !g.resolved).map((g) => (guidanceSeverity(g), g)) : []);
585	
586	// Record the optimize-loop's decision for a problem (⑥): merge a partial onto overlay.optimize[key]
587	// — e.g. { closed:true, decision } to stop iterating, or { verdicts } to remember the verdict count
588	// at the last 'iterate' so the loop only re-decides after a NEW round. Stamps `at`. Returns overlay.
589	function setOptimize(overlay, key, data) {
590	  if (!overlay.optimize) overlay.optimize = {};
591	  overlay.optimize[key] = { ...(overlay.optimize[key] || {}), ...data, at: new Date().toISOString() };
592	  return overlay;
593	}
594	
595	// Bump the graph-change epoch (a note/task node was added). Monotonic; initializes a legacy overlay
596	// that predates the field. Returns the new epoch. The edge-judge re-pulls notes whose judgedAtEpoch
597	// is below this, so a NEW node makes previously-judged neighbors eligible to re-adjudicate.
598	function bumpEpoch(overlay) {
599	  overlay.epoch = (overlay.epoch || 0) + 1;
600	  return overlay.epoch;
601	}
602	
603	// Set an on-complete interface summary for a task. Stored in overlay.summaries. Truncates to 2000
604	// chars (same cap as the daemon endpoint). Returns overlay.
605	function setSummary(overlay, key, summary) {
606	  overlay.summaries[key] = String(summary).slice(0, 2000);
607	  return overlay;
608	}
609	
610	// Merge extra runtime fields onto a guidance item by id. Used to stamp LOCAL annotations
611	// (e.g. verdictKey, sessionKey) onto items right after addGuidance returns the id, without
612	// touching the shared schema fields. No-ops silently when the id is not found. Returns overlay.
613	function annotateGuidance(overlay, id, fields) {
614	  if (!Array.isArray(overlay.guidance)) return overlay;
615	  const item = overlay.guidance.find((g) => g.id === id);
616	  if (item && fields && typeof fields === 'object') Object.assign(item, fields);
617	  return overlay;
618	}
619	
620	// Re-point context edges that touch any key in `supersededKeys` to `keepKey`, then drop
621	// self-loops and deduplicate by (from, to, fromWorkspace, kind). Used after a node-dedup
622	// consolidation so the keeper inherits the cluster's edges and nothing dangles to a now-hidden
623	// note. `supersededKeys` should be 'note:'-prefixed. Returns overlay.
624	function repointEdges(overlay, supersededKeys, keepKey) {
625	  const sup = new Set(supersededKeys);
626	  for (const e of overlay.edges) {
627	    if (e.kind !== 'context') continue;
628	    if (sup.has(e.from)) e.from = keepKey;
629	    if (sup.has(e.to)) e.to = keepKey;
630	  }
631	  const seen = new Set();
632	  overlay.edges = overlay.edges.filter((e) => {
633	    if (e.from === e.to) return false;                                   // self-loop
634	    const sig = `${e.from}>>${e.to}>>${e.fromWorkspace || ''}>>${e.kind || 'blocking'}`;
635	    if (seen.has(sig)) return false;
636	    seen.add(sig);
637	    return true;
638	  });
639	  return overlay;
640	}
641	
642	// Retrieve diagnostics for a workspace. Returns the diagnostics object or null if none exist.
643	// Shape: { lastError: string|null, errorCount: number, lastChecked: string }
644	function getDiagnostics(workspace) {
645	  try {
646	    const data = JSON.parse(fs.readFileSync(diagnosticsFileFor(workspace), 'utf8'));
647	    return data;
648	  } catch {
649	    return null;
650	  }
651	}
652	
653	// Store diagnostics for a workspace. Persists atomically (temp + rename pattern).
654	// value should be: { lastError: string|null, errorCount: number, lastChecked: string }
655	function setDiagnostics(workspace, value) {
656	  fs.mkdirSync(DIR, { recursive: true });
657	  const dest = diagnosticsFileFor(workspace);
658	  const tmp = `${dest}.${process.pid}.tmp`;
659	  fs.writeFileSync(tmp, JSON.stringify(value, null, 2));
660	  fs.renameSync(tmp, dest);
661	  return value;
662	}
663	
664	module.exports = { load, save, fileFor, addEdge, removeEdge, setStatus, setGit, setRepo, setTestCmd, testCmdFor, setMetricSpec, setMeasurement, setBenchmark, setSnapshot, addNoteNode, supersedeNote, noteChain, addGuidance, resolveGuidance, pendingGuidance, markClusterDistinct, isClusterDistinct, clusterSig, setOptimize, bumpEpoch, edgeWeight, DEFAULT_CONTEXT_WEIGHT, EMPTY, setSummary, annotateGuidance, repointEdges, getDiagnostics, setDiagnostics };
